.index-menu-item {
  background-color: var(--color-bg);
}

.index-menu-item h3 {
  color: var(--color-primary);
}

.index-price {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: var(--spacing-sm);
}

.index-specials {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-bg);
}

.index-specials h2 {
  text-align: center;
  color: var(--color-primary);
}

