  background-color: var(--color-primary);
  color: var(--color-bg);
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
}

.index-cta h2 {
  color: var(--color-bg);
}

.index-cta p {
  font-size: 1.1rem;
