    font-size: 1.8rem;
  }

  .index-hero-tagline {
    font-size: 1rem;
  }

  .index-schedule-grid {
    grid-template-columns: 1fr;
  }

  .index-specials-grid {
    grid-template-columns: 1fr;
  }

  .index-menu {
    padding: var(--spacing-lg) 0;
  }

  .index-specials {
    padding: var(--spacing-lg) 0;
  }
}

